using System.Collections.ObjectModel;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using Microsoft.Win32;
using SoopaDriveTool.Core;
namespace SoopaDriveTool.Windows;
public partial class MainWindow
{
    public class EditableWorkload{public string Name{get;set;}="Custom";public int BlockBytes{get;set;}=4096;public int QueueDepth{get;set;}=1;public int Threads{get;set;}=1;public bool Random{get;set;}=true;public int ReadPercent{get;set;}=70;public BenchmarkProfile Profile()=>new(Name,BlockBytes,QueueDepth,Threads,Random,ReadPercent);}
    Func<IReadOnlyList<BenchmarkProfile>?> BenchmarkEditor()
    {
        var enabled=new CheckBox{Content="Use custom workloads instead of the selected standard profile",Margin=new Thickness(0,12,0,12)};var rows=new ObservableCollection<EditableWorkload>{new()};var grid=new DataGrid{ItemsSource=rows,AutoGenerateColumns=false,CanUserAddRows=false,CanUserDeleteRows=true,MaxHeight=260,IsReadOnly=false};foreach(var (header,name) in new[]{("Name","Name"),("Block bytes","BlockBytes"),("Queue","QueueDepth"),("Threads","Threads"),("Read %","ReadPercent")})grid.Columns.Add(new DataGridTextColumn{Header=header,Binding=new Binding(name){Mode=BindingMode.TwoWay,UpdateSourceTrigger=UpdateSourceTrigger.LostFocus}});grid.Columns.Add(new DataGridCheckBoxColumn{Header="Random",Binding=new Binding("Random"){Mode=BindingMode.TwoWay}});
        List<BenchmarkProfile> Values(){grid.CommitEdit(DataGridEditingUnit.Cell,true);grid.CommitEdit(DataGridEditingUnit.Row,true);var values=rows.Select(r=>r.Profile()).ToList();BenchmarkService.ValidateProfiles(values);return values;}
        var actions=new WrapPanel();actions.Children.Add(Btn("Add workload",()=>{if(rows.Count<16)rows.Add(new());}));actions.Children.Add(Btn("Save workload profile…",async()=>{var values=Values();var save=new SaveFileDialog{Filter="JSON workloads|*.json",FileName="SoopaDriveTool-workloads.json"};if(save.ShowDialog(this)==true)await Data.SaveAsync(save.FileName,values);}));actions.Children.Add(Btn("Load workload profile…",async()=>{var file=PickFile("JSON workloads|*.json");if(file==null)return;if(new FileInfo(file).Length>65536)throw new IOException("Oversized workload profile.");var values=JsonSerializer.Deserialize<List<BenchmarkProfile>>(await File.ReadAllTextAsync(file),Data.Json)??[];BenchmarkService.ValidateProfiles(values);rows.Clear();foreach(var v in values)rows.Add(new(){Name=v.Name,BlockBytes=v.BlockBytes,QueueDepth=v.QueueDepth,Threads=v.Threads,Random=v.Random,ReadPercent=v.ReadPercent??100});enabled.IsChecked=true;}));body.Children.Add(Card(new Expander{Header="Custom workloads and saved profiles",Content=Stack(enabled,grid,actions),IsExpanded=false}));return ()=>enabled.IsChecked==true?Values():null;
    }
    void BenchmarkComparison()
    {
        string folder=Path.Combine(Data.Home,"benchmarks");var files=Directory.Exists(folder)?Directory.GetFiles(folder,"*.json").OrderDescending().Take(100).ToArray():[];if(files.Length==0)return;ComboBox left=new ComboBox{ItemsSource=files,SelectedIndex=0},right=new ComboBox{ItemsSource=files,SelectedIndex=Math.Min(1,files.Length-1)};var chart=new StackPanel();
        body.Children.Add(Card(Stack(T("Compare saved runs",19,Ink,true),left,right,Btn("Compare throughput",async()=>{if(left.SelectedItem is not string a||right.SelectedItem is not string b)return;var one=JsonSerializer.Deserialize<BenchmarkRun>(await File.ReadAllTextAsync(a),Data.Json)!;var two=JsonSerializer.Deserialize<BenchmarkRun>(await File.ReadAllTextAsync(b),Data.Json)!;chart.Children.Clear();chart.Children.Add(T($"A: {one.CreatedUtc:u} · {one.FileMiB} MiB, {one.Seconds}s, {one.Profile}\nB: {two.CreatedUtc:u} · {two.FileMiB} MiB, {two.Seconds}s, {two.Profile}",12,Muted));var comparisons=one.Results.Select(x=>new{x.Name,x.Mode,A=x.MBps,B=two.Results.FirstOrDefault(r=>r.Name==x.Name&&r.Mode==x.Mode)?.MBps}).Where(x=>x.B.HasValue).ToList();double max=Math.Max(1,comparisons.SelectMany(x=>new[]{x.A,x.B!.Value}).DefaultIfEmpty(1).Max());foreach(var x in comparisons){chart.Children.Add(T(x.Name+" · "+x.Mode,12,Ink,true));chart.Children.Add(new Border{Height=18,Width=700*x.A/max,HorizontalAlignment=HorizontalAlignment.Left,Background=Accent,ToolTip=$"A: {x.A:0.00} MB/s",Margin=new Thickness(0,4,0,2)});chart.Children.Add(new Border{Height=18,Width=700*x.B!.Value/max,HorizontalAlignment=HorizontalAlignment.Left,Background=B("#2DB294"),ToolTip=$"B: {x.B:0.00} MB/s",Margin=new Thickness(0,2,0,10)});chart.Children.Add(T($"A {x.A:0.00} MB/s · B {x.B:0.00} MB/s · {(x.A>0?100*(x.B.Value/x.A-1):0):+0.0;-0.0;0}%",12,Muted));}if(comparisons.Count==0)chart.Children.Add(T("No matching workload/mode pairs. Compare runs using the same workload definitions.",12,Muted));}),chart)));
    }
}
